_POST_KEYS = {"at", "facts", "rules"}
_COMPILE_KEYS = {"at", "rules"}
_SCHEDULE_KEYS = {"start", "end", "rules"}
_COMPARE_KEYS = {"from", "to", "facts", "rules"}
_TIMELINE_KEYS = {"start", "end", "facts", "rules"}
_IMPACT_KEYS = {"from", "to", "cases", "rules"}
